"""A small in-memory RESTful API for tracking IOUs."""

import json


class RestAPI:
    """Expose the IOU database through ``get`` and ``post`` methods."""

    def __init__(self, database=None):
        self.database = database if database is not None else {"users": []}
        self._users = self.database.setdefault("users", [])
        self._normalise_database()

    @staticmethod
    def _parse_payload(payload):
        if payload is None:
            return {}
        if isinstance(payload, (dict, list)):
            return payload
        if isinstance(payload, bytes):
            payload = payload.decode("utf-8")
        return json.loads(payload)

    @staticmethod
    def _clean_amounts(amounts):
        cleaned = {}
        for name, amount in amounts.items():
            value = float(amount)
            if value:
                cleaned[name] = value
        return cleaned

    @staticmethod
    def _balance_of(user):
        return round(
            sum(user["owed_by"].values()) - sum(user["owes"].values()),
            10,
        )

    def _normalise_database(self):
        for user in self._users:
            owes = self._clean_amounts(user.get("owes", {}))
            owed_by = self._clean_amounts(user.get("owed_by", {}))
            user.clear()
            user.update(
                {
                    "name": user.get("name"),
                    "owes": owes,
                    "owed_by": owed_by,
                    "balance": round(
                        sum(owed_by.values()) - sum(owes.values()), 10
                    ),
                }
            )

    @staticmethod
    def _view(user):
        balance = RestAPI._balance_of(user)
        return {
            "name": user["name"],
            "owes": {name: amount for name, amount in user["owes"].items()},
            "owed_by": {
                name: amount for name, amount in user["owed_by"].items()
            },
            "balance": balance,
        }

    def _find_user(self, name):
        for user in self._users:
            if user["name"] == name:
                return user
        raise KeyError("Unknown user: {}".format(name))

    @staticmethod
    def _set_relation(holder, other, field, amount):
        """Set/remove one directed debt, keeping the two maps consistent."""
        if amount is None:
            amount = holder[field].get(other, 0.0)
        amount = round(float(amount), 10)
        if amount:
            holder[field][other] = amount
        else:
            holder[field].pop(other, None)

    @staticmethod
    def _route(route):
        return route.rstrip("/") or "/"

    def get(self, url, payload=None):
        if self._route(url) != "/users":
            raise ValueError("Unsupported GET route: {}".format(url))

        data = self._parse_payload(payload)
        users = self._users
        if isinstance(data, dict) and "users" in data:
            requested = set(data["users"])
            users = [user for user in users if user["name"] in requested]

        return json.dumps(
            {
                "users": [
                    self._view(user)
                    for user in sorted(users, key=lambda user: user["name"])
                ]
            }
        )

    def post(self, url, payload=None):
        route = self._route(url)
        data = self._parse_payload(payload)

        if route == "/add":
            name = data["user"]
            if any(user["name"] == name for user in self._users):
                raise ValueError("User already exists: {}".format(name))
            user = {"name": name, "owes": {}, "owed_by": {}, "balance": 0.0}
            self._users.append(user)
            return json.dumps(self._view(user))

        if route == "/iou":
            lender = self._find_user(data["lender"])
            borrower = self._find_user(data["borrower"])
            amount = float(data["amount"])

            if lender is borrower:
                affected = [lender]
            else:
                lender_name = lender["name"]
                borrower_name = borrower["name"]

                # Net the two users' existing debt with the new loan.  A
                # positive net means the borrower still owes the lender.
                net = (
                    borrower["owes"].get(lender_name, 0.0)
                    - lender["owes"].get(borrower_name, 0.0)
                    + amount
                )
                net = round(net, 10)

                for user, other in (
                    (lender, borrower_name),
                    (borrower, lender_name),
                ):
                    user["owes"].pop(other, None)
                    user["owed_by"].pop(other, None)

                if net > 0:
