                        borrower, lender_name, "owes", net
                    )
                    self._set_relation(
                        lender, borrower_name, "owed_by", net
                    )
                elif net < 0:
                    self._set_relation(
                        lender, borrower_name, "owes", -net
                    )
                    self._set_relation(
                        borrower, lender_name, "owed_by", -net
                    )

                lender["balance"] = self._balance_of(lender)
                borrower["balance"] = self._balance_of(borrower)
                affected = [lender, borrower]

            return json.dumps(
                {
                    "users": [
                        self._view(user)
                        for user in sorted(
                            affected, key=lambda user: user["name"]
                        )
                    ]
                }
            )

        raise ValueError("Unsupported POST route: {}".format(url))
